using System.IO;using System.Diagnostics;using System.Text.Json;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using RAWSelectionAssistant.Core.Services.Projects;using RAWSelectionAssistant.Services;using RAWSelectionAssistant.ViewModels;using RAWSelectionAssistant.Views;using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public class R55PolishTests
{
 static string Root=>Environment.GetEnvironmentVariable("KITAO_R55_POLISH_ROOT")??throw new InvalidOperationException("Explicit polish evidence root required");
 internal static async Task<ReferenceColorWorkspaceViewModel> OwnedWorkspace(){EnsureTestApplication();var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());foreach(var path in Directory.GetFiles(Path.Combine(Root,"../owned-inputs"),"*.jpg").Order().Take(100)){var hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(path)));var target=new ReferenceTargetItem(path){SourceHash=hash,IsSelected=true};var version=new StudioEditVersion(Guid.NewGuid(),"测试照片 · "+Path.GetFileNameWithoutExtension(path),DateTimeOffset.UnixEpoch,null,null,hash,null,null,null,ColorStudioMatchEngine.Stable,MatchV4ExecutionMode.Auto){IsOriginal=true};target.ActiveEditVersionId=version.Id;target.EditVersions.Add(version);vm.Targets.Add(target);}vm.PinSelectedViewingVariants();await vm.PrepareViewingTableAsync();return vm;}
 internal static void Layout(FrameworkElement view,int width=1366){view.Measure(new Size(width,width==1366?768:1080));view.Arrange(new Rect(0,0,width,width==1366?768:1080));view.UpdateLayout();}
 [TestMethod]public Task ProfileOpenPanelsAndLayoutGestures()=>RunSta(async()=>{Directory.CreateDirectory(Root);using var vm=await OwnedWorkspace();var table=new StudioViewingTableView(vm);Layout(table);await table.RefreshAsync();table.SelectForTest(vm.ViewingFrames[0]);table.OpenInfoSidebarForTest();ViewingTableDiagnostics.Reset();var clock=Stopwatch.StartNew();await table.RefreshAsync();Layout(table);var warm=clock.Elapsed.TotalMilliseconds;var openProfile=ViewingTableDiagnostics.Snapshot();ViewingTableDiagnostics.Reset();var item=vm.ViewingTable.Items[0];clock.Restart();vm.BeginViewingGesture();for(int n=0;n<20;n++)vm.SetViewingPlacement(item.TargetId,item.VariantId,item.X+n,item.Y+n,item.Scale,item.Rotation);vm.CommitViewingGesture();var placementMs=clock.Elapsed.TotalMilliseconds;var layoutProfile=ViewingTableDiagnostics.Snapshot();ViewingTableDiagnostics.Reset();clock.Restart();for(int n=0;n<20;n++)vm.SetViewingBrightness(.5+n*.05);var brightnessMs=clock.Elapsed.TotalMilliseconds;var brightnessProfile=ViewingTableDiagnostics.Snapshot();await File.WriteAllTextAsync(Path.Combine(Root,"PANELS_GESTURES.json"),JsonSerializer.Serialize(new{warmOpenMs=warm,openProfile,placementMs,layoutProfile,brightnessMs,brightnessProfile,scope="20 model gesture updates, NOT drag frame rate; actual controls attached offscreen"},new JsonSerializerOptions{WriteIndented=true}));table.Close();new ViewingPreferences().Save();});
 [TestMethod]public Task PhotoLabelContextAndFilmActionStatesUseRealControls()=>RunSta(async()=>{new ViewingPreferences().Save();using var vm=await OwnedWorkspace();var view=new StudioViewingTableView(vm);Layout(view);await view.RefreshAsync();var first=vm.ViewingFrames[0];view.SelectForTest(first);Layout(view);var bounds=view.CardContentBounds(first.Item.VariantId);Assert.IsTrue(bounds.Image.Bottom+4<=bounds.Label.Top);var card=view.CardSurfaceBounds(first.Item.VariantId);var context=view.ContextBounds;Assert.IsFalse(card.IntersectsWith(context));foreach(var angle in new[]{37d,90d,154d}){vm.SetViewingPlacement(first.Item.TargetId,first.Item.VariantId,1050,550,.8,angle);Layout(view);view.SelectForTest(first);Layout(view);context=view.ContextBounds;Assert.IsTrue(context.Left>=0&&context.Top>=0);Assert.IsTrue(context.Right<=view.CenterSize.Width+1&&context.Bottom<=view.CenterSize.Height+1);}view.OpenFilmSidebarForTest();await view.PreflightForTest();Assert.IsFalse(view.CancelActionVisible);Assert.IsFalse(view.ResultActionsVisible);Assert.AreEqual("100%",view.AmountReadout);Assert.AreEqual("0%",view.GrainReadout);view.Close();new ViewingPreferences().Save();});

}
